INSERT INTO events (code, title, body, area_code, min_realm_order, max_realm_order, weight, choices, is_story) VALUES
('event_mortal_01', '尘世·旧碑残文', '荒草间露出半截古碑，碑面纹路被风雨磨去大半。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 70, '[{"text":"拂去苔痕细读","result":"你辨认出几句残文，也在碑后找到遗物。","effects":{"items":{"mat_mortal_1":2},"qi":30,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世清露。","effects":{"items":{"mat_mortal_2":2},"spirit_stones":3}}]', false),
('event_mortal_02', '尘世·负伤采药人', '一名采药人倚着岩壁包扎伤口，药篓散落在旁。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 85, '[{"text":"上前搭手","result":"对方谢过援手，与你交换了辨药心得。","effects":{"items":{"mat_mortal_2":3},"qi":30,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世玄砂。","effects":{"items":{"mat_mortal_3":2},"spirit_stones":3}}]', false),
('event_mortal_03', '尘世·隐秘石洞', '山壁后传来空洞回声，一道仅容侧身通过的裂隙藏在藤蔓后。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 100, '[{"text":"点灯入洞","result":"洞中没有妖物，只有前人留下的瓶罐与残页。","effects":{"items":{"mat_mortal_3":4},"qi":30,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世玉根。","effects":{"items":{"mat_mortal_4":2},"spirit_stones":3}}]', false),
('event_mortal_04', '尘世·雨后药坡', '骤雨刚停，坡地草叶挂满水珠，泥土中透出清苦药香。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 115, '[{"text":"按叶脉采集","result":"你避开有毒植株，采到一批新鲜材料。","effects":{"items":{"mat_mortal_4":2},"qi":30}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世石髓。","effects":{"items":{"mat_mortal_5":2},"spirit_stones":3}}]', false),
('event_mortal_05', '尘世·山中小市', '几名行脚人临时支起布棚，以物易物，天黑前便会散去。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 70, '[{"text":"拿材料交换","result":"你换到少见的手抄本，也听说了附近的产材地点。","effects":{"items":{"mat_mortal_5":3},"qi":30,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世灵果。","effects":{"items":{"mat_mortal_6":2},"spirit_stones":3}}]', false),
('event_mortal_06', '尘世·灵兽足迹', '泥地上留着一串泛光足印，延伸向林木深处。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 85, '[{"text":"保持距离追踪","result":"足迹尽头散落着灵兽啃食后留下的药材。","effects":{"items":{"mat_mortal_6":4},"qi":30}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世灵叶。","effects":{"items":{"mat_mortal_1":2},"spirit_stones":3}}]', false),
('event_mortal_07', '尘世·前人丹室', '焦黑石门后是一间废弃丹室，炉灰仍有微弱余温。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 100, '[{"text":"清理炉台","result":"你从夹层找到一页丹方，并收起尚能使用的药材。","effects":{"items":{"mat_mortal_1":2},"qi":30,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世清露。","effects":{"items":{"mat_mortal_2":2},"spirit_stones":3}}]', false),
('event_mortal_08', '尘世·风中经声', '风穿过石孔，竟像有人在远处诵读经文，字句若隐若现。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 115, '[{"text":"静坐聆听","result":"你记下几段运气法门，心境也随之澄明。","effects":{"items":{"mat_mortal_2":3},"qi":30,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世玄砂。","effects":{"items":{"mat_mortal_3":2},"spirit_stones":3}}]', false),
('event_mortal_09', '尘世·断桥彼端', '旧桥断在山涧中央，对岸石台上生着几株罕见灵草。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 70, '[{"text":"寻找稳妥路径","result":"绕行虽费时间，却平安带回了灵草。","effects":{"items":{"mat_mortal_3":4},"qi":30}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世玉根。","effects":{"items":{"mat_mortal_4":2},"spirit_stones":3}}]', false),
('event_mortal_10', '尘世·夜宿古亭', '暮色将合，古亭梁上挂着褪色木牌，桌面留有新鲜墨迹。这里是落霞村，任何细小痕迹都可能与凡人修行有关。', 'luoxia', 0, 0, 85, '[{"text":"燃灯查看","result":"墨迹记载了附近秘径，桌下还压着一只旧木匣。","effects":{"items":{"mat_mortal_4":2},"qi":30,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些尘世石髓。","effects":{"items":{"mat_mortal_5":2},"spirit_stones":3}}]', false),
('event_lianpi_01', '铜皮·旧碑残文', '荒草间露出半截古碑，碑面纹路被风雨磨去大半。这里是青云山脚，任何细小痕迹都可能与练皮境修行有关。', 'qingyun_foothill', 1, 4, 70, '[{"text":"拂去苔痕细读","result":"你辨认出几句残文，也在碑后找到遗物。","effects":{"items":{"mat_lianpi_1":2},"qi":50,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些铜皮清露。","effects":{"items":{"mat_lianpi_2":2},"spirit_stones":4}}]', false),
('event_lianpi_02', '铜皮·负伤采药人', '一名采药人倚着岩壁包扎伤口，药篓散落在旁。这里是青云山脚，任何细小痕迹都可能与练皮境修行有关。', 'qingyun_foothill', 1, 4, 85, '[{"text":"上前搭手","result":"对方谢过援手，与你交换了辨药心得。","effects":{"items":{"mat_lianpi_2":3},"qi":50,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些铜皮玄砂。","effects":{"items":{"mat_lianpi_3":2},"spirit_stones":4}}]', false),
('event_lianpi_03', '铜皮·隐秘石洞', '山壁后传来空洞回声，一道仅容侧身通过的裂隙藏在藤蔓后。这里是青云山脚，任何细小痕迹都可能与练皮境修行有关。', 'qingyun_foothill', 1, 4, 100, '[{"text":"点灯入洞","result":"洞中没有妖物，只有前人留下的瓶罐与残页。","effects":{"items":{"mat_lianpi_3":4},"qi":50,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些铜皮玉根。","effects":{"items":{"mat_lianpi_4":2},"spirit_stones":4}}]', false),
('event_lianpi_04', '铜皮·雨后药坡', '骤雨刚停，坡地草叶挂满水珠，泥土中透出清苦药香。这里是青云山脚，任何细小痕迹都可能与练皮境修行有关。', 'qingyun_foothill', 1, 4, 115, '[{"text":"按叶脉采集","result":"你避开有毒植株，采到一批新鲜材料。","effects":{"items":{"mat_lianpi_4":2},"qi":50}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些铜皮石髓。","effects":{"items":{"mat_lianpi_5":2},"spirit_stones":4}}]', false),
('event_lianpi_05', '铜皮·山中小市', '几名行脚人临时支起布棚，以物易物，天黑前便会散去。这里是青云山脚，任何细小痕迹都可能与练皮境修行有关。', 'qingyun_foothill', 1, 4, 70, '[{"text":"拿材料交换","result":"你换到少见的手抄本，也听说了附近的产材地点。","effects":{"items":{"mat_lianpi_5":3},"qi":50,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些铜皮灵果。","effects":{"items":{"mat_lianpi_6":2},"spirit_stones":4}}]', false),
