('event_yijin_07', '玉筋·前人丹室', '焦黑石门后是一间废弃丹室，炉灰仍有微弱余温。这里是迷雾林，任何细小痕迹都可能与易筋境修行有关。', 'mist_forest', 9, 12, 100, '[{"text":"清理炉台","result":"你从夹层找到一页丹方，并收起尚能使用的药材。","effects":{"items":{"mat_yijin_1":2},"qi":210,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些玉筋清露。","effects":{"items":{"mat_yijin_2":2},"spirit_stones":12}}]', false),
('event_yijin_08', '玉筋·风中经声', '风穿过石孔，竟像有人在远处诵读经文，字句若隐若现。这里是迷雾林，任何细小痕迹都可能与易筋境修行有关。', 'mist_forest', 9, 12, 115, '[{"text":"静坐聆听","result":"你记下几段运气法门，心境也随之澄明。","effects":{"items":{"mat_yijin_2":3},"qi":210,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些玉筋玄砂。","effects":{"items":{"mat_yijin_3":2},"spirit_stones":12}}]', false),
('event_yijin_09', '玉筋·断桥彼端', '旧桥断在山涧中央，对岸石台上生着几株罕见灵草。这里是迷雾林，任何细小痕迹都可能与易筋境修行有关。', 'mist_forest', 9, 12, 70, '[{"text":"寻找稳妥路径","result":"绕行虽费时间，却平安带回了灵草。","effects":{"items":{"mat_yijin_3":4},"qi":210}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些玉筋玉根。","effects":{"items":{"mat_yijin_4":2},"spirit_stones":12}}]', false),
('event_yijin_10', '玉筋·夜宿古亭', '暮色将合，古亭梁上挂着褪色木牌，桌面留有新鲜墨迹。这里是迷雾林，任何细小痕迹都可能与易筋境修行有关。', 'mist_forest', 9, 12, 85, '[{"text":"燃灯查看","result":"墨迹记载了附近秘径，桌下还压着一只旧木匣。","effects":{"items":{"mat_yijin_4":2},"qi":210,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些玉筋石髓。","effects":{"items":{"mat_yijin_5":2},"spirit_stones":12}}]', false),
('event_xisui_01', '净髓·旧碑残文', '荒草间露出半截古碑，碑面纹路被风雨磨去大半。这里是清泉崖，任何细小痕迹都可能与洗髓境修行有关。', 'clear_spring_cliff', 13, 16, 70, '[{"text":"拂去苔痕细读","result":"你辨认出几句残文，也在碑后找到遗物。","effects":{"items":{"mat_xisui_1":2},"qi":290,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些净髓清露。","effects":{"items":{"mat_xisui_2":2},"spirit_stones":16}}]', false),
('event_xisui_02', '净髓·负伤采药人', '一名采药人倚着岩壁包扎伤口，药篓散落在旁。这里是清泉崖，任何细小痕迹都可能与洗髓境修行有关。', 'clear_spring_cliff', 13, 16, 85, '[{"text":"上前搭手","result":"对方谢过援手，与你交换了辨药心得。","effects":{"items":{"mat_xisui_2":3},"qi":290,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些净髓玄砂。","effects":{"items":{"mat_xisui_3":2},"spirit_stones":16}}]', false),
('event_xisui_03', '净髓·隐秘石洞', '山壁后传来空洞回声，一道仅容侧身通过的裂隙藏在藤蔓后。这里是清泉崖，任何细小痕迹都可能与洗髓境修行有关。', 'clear_spring_cliff', 13, 16, 100, '[{"text":"点灯入洞","result":"洞中没有妖物，只有前人留下的瓶罐与残页。","effects":{"items":{"mat_xisui_3":4},"qi":290,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些净髓玉根。","effects":{"items":{"mat_xisui_4":2},"spirit_stones":16}}]', false),
('event_xisui_04', '净髓·雨后药坡', '骤雨刚停，坡地草叶挂满水珠，泥土中透出清苦药香。这里是清泉崖，任何细小痕迹都可能与洗髓境修行有关。', 'clear_spring_cliff', 13, 16, 115, '[{"text":"按叶脉采集","result":"你避开有毒植株，采到一批新鲜材料。","effects":{"items":{"mat_xisui_4":2},"qi":290}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些净髓石髓。","effects":{"items":{"mat_xisui_5":2},"spirit_stones":16}}]', false),
