('event_tianren_06', '天感·灵兽足迹', '泥地上留着一串泛光足印，延伸向林木深处。这里是天镜湖，任何细小痕迹都可能与天人境修行有关。', 'mirror_lake', 21, 24, 85, '[{"text":"保持距离追踪","result":"足迹尽头散落着灵兽啃食后留下的药材。","effects":{"items":{"mat_tianren_6":4},"qi":450}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些天感灵叶。","effects":{"items":{"mat_tianren_1":2},"spirit_stones":24}}]', false),
('event_tianren_07', '天感·前人丹室', '焦黑石门后是一间废弃丹室，炉灰仍有微弱余温。这里是天镜湖，任何细小痕迹都可能与天人境修行有关。', 'mirror_lake', 21, 24, 100, '[{"text":"清理炉台","result":"你从夹层找到一页丹方，并收起尚能使用的药材。","effects":{"items":{"mat_tianren_1":2},"qi":450,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些天感清露。","effects":{"items":{"mat_tianren_2":2},"spirit_stones":24}}]', false),
('event_tianren_08', '天感·风中经声', '风穿过石孔，竟像有人在远处诵读经文，字句若隐若现。这里是天镜湖，任何细小痕迹都可能与天人境修行有关。', 'mirror_lake', 21, 24, 115, '[{"text":"静坐聆听","result":"你记下几段运气法门，心境也随之澄明。","effects":{"items":{"mat_tianren_2":3},"qi":450,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些天感玄砂。","effects":{"items":{"mat_tianren_3":2},"spirit_stones":24}}]', false),
('event_tianren_09', '天感·断桥彼端', '旧桥断在山涧中央，对岸石台上生着几株罕见灵草。这里是天镜湖，任何细小痕迹都可能与天人境修行有关。', 'mirror_lake', 21, 24, 70, '[{"text":"寻找稳妥路径","result":"绕行虽费时间，却平安带回了灵草。","effects":{"items":{"mat_tianren_3":4},"qi":450}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些天感玉根。","effects":{"items":{"mat_tianren_4":2},"spirit_stones":24}}]', false),
('event_tianren_10', '天感·夜宿古亭', '暮色将合，古亭梁上挂着褪色木牌，桌面留有新鲜墨迹。这里是天镜湖，任何细小痕迹都可能与天人境修行有关。', 'mirror_lake', 21, 24, 85, '[{"text":"燃灯查看","result":"墨迹记载了附近秘径，桌下还压着一只旧木匣。","effects":{"items":{"mat_tianren_4":2},"qi":450,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些天感石髓。","effects":{"items":{"mat_tianren_5":2},"spirit_stones":24}}]', false),
('event_lianqi_01', '灵息·旧碑残文', '荒草间露出半截古碑，碑面纹路被风雨磨去大半。这里是灵脉谷，任何细小痕迹都可能与炼气期修行有关。', 'spirit_vein_valley', 25, 28, 70, '[{"text":"拂去苔痕细读","result":"你辨认出几句残文，也在碑后找到遗物。","effects":{"items":{"mat_lianqi_1":2},"qi":530,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些灵息清露。","effects":{"items":{"mat_lianqi_2":2},"spirit_stones":28}}]', false),
('event_lianqi_02', '灵息·负伤采药人', '一名采药人倚着岩壁包扎伤口，药篓散落在旁。这里是灵脉谷，任何细小痕迹都可能与炼气期修行有关。', 'spirit_vein_valley', 25, 28, 85, '[{"text":"上前搭手","result":"对方谢过援手，与你交换了辨药心得。","effects":{"items":{"mat_lianqi_2":3},"qi":530,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些灵息玄砂。","effects":{"items":{"mat_lianqi_3":2},"spirit_stones":28}}]', false),
('event_lianqi_03', '灵息·隐秘石洞', '山壁后传来空洞回声，一道仅容侧身通过的裂隙藏在藤蔓后。这里是灵脉谷，任何细小痕迹都可能与炼气期修行有关。', 'spirit_vein_valley', 25, 28, 100, '[{"text":"点灯入洞","result":"洞中没有妖物，只有前人留下的瓶罐与残页。","effects":{"items":{"mat_lianqi_3":4},"qi":530,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些灵息玉根。","effects":{"items":{"mat_lianqi_4":2},"spirit_stones":28}}]', false),
