('event_jindan_06', '丹火·灵兽足迹', '泥地上留着一串泛光足印，延伸向林木深处。这里是丹霞峰，任何细小痕迹都可能与金丹期修行有关。', 'alchemy_peak', 33, 36, 85, '[{"text":"保持距离追踪","result":"足迹尽头散落着灵兽啃食后留下的药材。","effects":{"items":{"mat_jindan_6":4},"qi":690}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些丹火灵叶。","effects":{"items":{"mat_jindan_1":2},"spirit_stones":36}}]', false),
('event_jindan_07', '丹火·前人丹室', '焦黑石门后是一间废弃丹室，炉灰仍有微弱余温。这里是丹霞峰，任何细小痕迹都可能与金丹期修行有关。', 'alchemy_peak', 33, 36, 100, '[{"text":"清理炉台","result":"你从夹层找到一页丹方，并收起尚能使用的药材。","effects":{"items":{"mat_jindan_1":2},"qi":690,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些丹火清露。","effects":{"items":{"mat_jindan_2":2},"spirit_stones":36}}]', false),
('event_jindan_08', '丹火·风中经声', '风穿过石孔，竟像有人在远处诵读经文，字句若隐若现。这里是丹霞峰，任何细小痕迹都可能与金丹期修行有关。', 'alchemy_peak', 33, 36, 115, '[{"text":"静坐聆听","result":"你记下几段运气法门，心境也随之澄明。","effects":{"items":{"mat_jindan_2":3},"qi":690,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些丹火玄砂。","effects":{"items":{"mat_jindan_3":2},"spirit_stones":36}}]', false),
('event_jindan_09', '丹火·断桥彼端', '旧桥断在山涧中央，对岸石台上生着几株罕见灵草。这里是丹霞峰，任何细小痕迹都可能与金丹期修行有关。', 'alchemy_peak', 33, 36, 70, '[{"text":"寻找稳妥路径","result":"绕行虽费时间，却平安带回了灵草。","effects":{"items":{"mat_jindan_3":4},"qi":690}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些丹火玉根。","effects":{"items":{"mat_jindan_4":2},"spirit_stones":36}}]', false),
('event_jindan_10', '丹火·夜宿古亭', '暮色将合，古亭梁上挂着褪色木牌，桌面留有新鲜墨迹。这里是丹霞峰，任何细小痕迹都可能与金丹期修行有关。', 'alchemy_peak', 33, 36, 85, '[{"text":"燃灯查看","result":"墨迹记载了附近秘径，桌下还压着一只旧木匣。","effects":{"items":{"mat_jindan_4":2},"qi":690,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些丹火石髓。","effects":{"items":{"mat_jindan_5":2},"spirit_stones":36}}]', false),
('event_yuanying_01', '婴息·旧碑残文', '荒草间露出半截古碑，碑面纹路被风雨磨去大半。这里是古魂遗墟，任何细小痕迹都可能与元婴期修行有关。', 'ancient_soul_ruins', 37, 40, 70, '[{"text":"拂去苔痕细读","result":"你辨认出几句残文，也在碑后找到遗物。","effects":{"items":{"mat_yuanying_1":2},"qi":770,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些婴息清露。","effects":{"items":{"mat_yuanying_2":2},"spirit_stones":40}}]', false),
('event_yuanying_02', '婴息·负伤采药人', '一名采药人倚着岩壁包扎伤口，药篓散落在旁。这里是古魂遗墟，任何细小痕迹都可能与元婴期修行有关。', 'ancient_soul_ruins', 37, 40, 85, '[{"text":"上前搭手","result":"对方谢过援手，与你交换了辨药心得。","effects":{"items":{"mat_yuanying_2":3},"qi":770,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些婴息玄砂。","effects":{"items":{"mat_yuanying_3":2},"spirit_stones":40}}]', false),
('event_yuanying_03', '婴息·隐秘石洞', '山壁后传来空洞回声，一道仅容侧身通过的裂隙藏在藤蔓后。这里是古魂遗墟，任何细小痕迹都可能与元婴期修行有关。', 'ancient_soul_ruins', 37, 40, 100, '[{"text":"点灯入洞","result":"洞中没有妖物，只有前人留下的瓶罐与残页。","effects":{"items":{"mat_yuanying_3":4},"qi":770,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些婴息玉根。","effects":{"items":{"mat_yuanying_4":2},"spirit_stones":40}}]', false),
