('event_dacheng_05', '渡劫·山中小市', '几名行脚人临时支起布棚，以物易物，天黑前便会散去。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 70, '[{"text":"拿材料交换","result":"你换到少见的手抄本，也听说了附近的产材地点。","effects":{"items":{"mat_dacheng_5":3},"qi":930,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫灵果。","effects":{"items":{"mat_dacheng_6":2},"spirit_stones":48}}]', false),
('event_dacheng_06', '渡劫·灵兽足迹', '泥地上留着一串泛光足印，延伸向林木深处。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 85, '[{"text":"保持距离追踪","result":"足迹尽头散落着灵兽啃食后留下的药材。","effects":{"items":{"mat_dacheng_6":4},"qi":930}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫灵叶。","effects":{"items":{"mat_dacheng_1":2},"spirit_stones":48}}]', false),
('event_dacheng_07', '渡劫·前人丹室', '焦黑石门后是一间废弃丹室，炉灰仍有微弱余温。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 100, '[{"text":"清理炉台","result":"你从夹层找到一页丹方，并收起尚能使用的药材。","effects":{"items":{"mat_dacheng_1":2},"qi":930,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫清露。","effects":{"items":{"mat_dacheng_2":2},"spirit_stones":48}}]', false),
('event_dacheng_08', '渡劫·风中经声', '风穿过石孔，竟像有人在远处诵读经文，字句若隐若现。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 115, '[{"text":"静坐聆听","result":"你记下几段运气法门，心境也随之澄明。","effects":{"items":{"mat_dacheng_2":3},"qi":930,"discover_technique":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫玄砂。","effects":{"items":{"mat_dacheng_3":2},"spirit_stones":48}}]', false),
('event_dacheng_09', '渡劫·断桥彼端', '旧桥断在山涧中央，对岸石台上生着几株罕见灵草。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 70, '[{"text":"寻找稳妥路径","result":"绕行虽费时间，却平安带回了灵草。","effects":{"items":{"mat_dacheng_3":4},"qi":930}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫玉根。","effects":{"items":{"mat_dacheng_4":2},"spirit_stones":48}}]', false),
('event_dacheng_10', '渡劫·夜宿古亭', '暮色将合，古亭梁上挂着褪色木牌，桌面留有新鲜墨迹。这里是天门绝域，任何细小痕迹都可能与大乘期修行有关。', 'heaven_gate', 45, 48, 85, '[{"text":"燃灯查看","result":"墨迹记载了附近秘径，桌下还压着一只旧木匣。","effects":{"items":{"mat_dacheng_4":2},"qi":930,"discover_technique":true,"discover_recipe":true}},{"text":"谨慎查看四周","result":"你没有贸然深入，但在附近收集到一些渡劫石髓。","effects":{"items":{"mat_dacheng_5":2},"spirit_stones":48}}]', false)
